import heapq
succ=lambda n:[n+1,n+2]
def bfs(goal,start=1):
    frontier=[start]; expanded=[]
    while frontier:
        n=frontier.pop(0)                      # FIFO
        if n==goal: return expanded
        expanded.append(n)
        for s in succ(n):                      # children in ascending order
            if s not in expanded and s not in frontier: frontier.append(s)
def dfs(goal,start=1):
    frontier=[start]; expanded=[]
    while frontier:
        n=frontier.pop()                       # LIFO
        if n==goal: return expanded
        expanded.append(n)
        for s in reversed(succ(n)):            # push larger first so smaller is expanded first
            if s not in expanded:
                if s in frontier: frontier.remove(s)
                frontier.append(s)
def ascending(goal,start=1):                    # 'unexpanded list kept in ascending order'
    frontier=[start]; expanded=[]
    while frontier:
        n=heapq.heappop(frontier)
        if n==goal: return expanded
        expanded.append(n)
        for s in succ(n):
            if s not in expanded and s not in frontier: heapq.heappush(frontier,s)
for f in (bfs,dfs,ascending): print(f.__name__, f(6), len(f(6)))
