def early(goal,lifo,start=1):                   # goal test when a state is generated
    frontier=[start]; expanded=[]
    while frontier:
        n=frontier.pop() if lifo else frontier.pop(0)
        expanded.append(n)
        kids=[s for s in succ(n) if s not in expanded]
        if goal in kids: return expanded
        for s in (reversed(kids) if lifo else kids):
            if lifo and s in frontier: frontier.remove(s)
            if lifo or s not in frontier: frontier.append(s)
print('goal test on generation: BFS',early(6,False),'DFS',early(6,True))  # both [1,2,3,4]
